		}
		clearFilterURL := "/api/admin/uploads"
		if len(params) > 0 {
			clearFilterURL += "?" + strings.Join(params, "&")
		}
		html += ` | <strong>Filtered by User ID:</strong> ` + userID + ` <a href="` + clearFilterURL + `">[Clear Filter]</a>`
