		}
		return "?" + strings.Join(params, "&")
	}

	// Previous button
	if page > 1 {
		html += `<a href="` + buildURL(page-1) + `" class="page-btn">&laquo; Previous</a>`
	} else {
		html += `<span class="page-btn disabled">&laquo; Previous</span>`
