11→var queryDuckDBLogsToolDef = mcp.NewTool(
12→	"query_duckdb_logs",
13→	mcp.WithDescription(
14→		"Query MCP AI logs stored in DuckDB. Supports simple SQL SELECT queries. Available tables: mcp_ai_query_log (tool execution logs), mcp_query_log (tool usage stats), chat_questions (user questions and AI answers from web-chat and map widget with metadata: timestamp, question, answer, source, ip_address, user_agent, is_mobile, os, browser, country, accept_language, referer, session_id, history_length, model, cloudfront). All tables are shared via DuckLake.",
15→	),
