 87→func writeChunk(w http.ResponseWriter, c chunk) {
 88→	data, _ := json.Marshal(c)
 89→	data = append(data, '\n')
 90→	w.Write(data)
 91→	if f, ok := w.(http.Flusher); ok {
 92→		f.Flush()
 93→	}
 94→}
 95→
 96→func writeChunkBuffered(w http.ResponseWriter, c chunk, buffer *[]chunk, useBuffer bool) {
 97→	if useBuffer {
 98→		*buffer = append(*buffer, c)
 99→	} else {
100→		writeChunk(w, c)
101→	}
102→}
103→
104→func flushBuffer(w http.ResponseWriter, buffer []chunk) {
105→	for _, c := range buffer {
106→		writeChunk(w, c)
107→	}
108→}
