110→func callAnthropic(ctx context.Context, apiKey, model string, messages []anthropicMessage, tools []anthropicTool) (*anthropicResponse, error) {
111→	reqBody := anthropicRequest{
112→		Model:     model,
113→		MaxTokens: 4096,
114→		System:    webChatSystemPrompt,
115→		Messages:  messages,
116→		Tools:     tools,
117→	}
118→	body, err := json.Marshal(reqBody)
119→	if err != nil {
120→		return nil, err
121→	}
122→
123→	req, err := http.NewRequestWithContext(ctx, http.MethodPost, "https://api.anthropic.com/v1/messages", bytes.NewReader(body))
124→	if err != nil {
125→		return nil, err
126→	}
127→	req.Header.Set("Content-Type", "application/json")
128→	req.Header.Set("x-api-key", apiKey)
129→	req.Header.Set("anthropic-version", "2023-06-01")
130→
131→	resp, err := http.DefaultClient.Do(req)
132→	if err != nil {
133→		return nil, err
134→	}
135→	defer resp.Body.Close()
136→
137→	raw, err := io.ReadAll(resp.Body)
138→	if err != nil {
139→		return nil, err
140→	}
141→
142→	var ar anthropicResponse
143→	if err := json.Unmarshal(raw, &ar); err != nil {
144→		return nil, fmt.Errorf("parse response: %w", err)
145→	}
146→	if ar.Error != nil {
147→		return nil, fmt.Errorf("anthropic %s: %s", ar.Error.Type, ar.Error.Message)
148→	}
149→	return &ar, nil
150→}
