243→		tools := mcpToolsToAnthropic(toolsResult.Tools)
244→
245→		messages := chatReq.History
246→		if messages == nil {
247→			messages = []anthropicMessage{}
248→		}
249→		messages = append(messages, anthropicMessage{Role: "user", Content: chatReq.Message})
250→
251→		for {
252→			resp, err := callAnthropic(ctx, apiKey, model, messages, tools)
253→			if err != nil {
254→				writeChunkBuffered(w, chunk{Type: "error", Error: err.Error()}, &buffer, isCloudFront)
255→				if isCloudFront {
256→					flushBuffer(w, buffer)
257→				}
258→				return
259→			}
260→
261→			messages = append(messages, anthropicMessage{
262→				Role:    "assistant",
263→				Content: resp.Content,
264→			})
265→
266→			var toolUses []contentBlock
267→			for _, block := range resp.Content {
268→				switch block.Type {
269→				case "text":
270→					answerText.WriteString(block.Text)
271→					writeChunkBuffered(w, chunk{Type: "text", Text: block.Text}, &buffer, isCloudFront)
272→				case "tool_use":
273→					toolUses = append(toolUses, block)
274→				}
275→			}
276→
277→			if resp.StopReason == "end_turn" || len(toolUses) == 0 {
278→				break
279→			}
280→
281→			var toolResults []contentBlock
282→			for _, tu := range toolUses {
283→				var args map[string]any
284→				_ = json.Unmarshal(tu.Input, &args)
285→
286→				callReq := mcp.CallToolRequest{}
287→				callReq.Params.Name = tu.Name
288→				callReq.Params.Arguments = args
289→
290→				var resultText string
291→				toolResult, err := mc.CallTool(ctx, callReq)
292→				if err != nil {
293→					resultText = fmt.Sprintf("tool error: %v", err)
294→				} else {
295→					for _, c := range toolResult.Content {
296→						if tc, ok := c.(mcp.TextContent); ok {
297→							resultText += tc.Text
298→						}
299→					}
300→				}
301→
302→				toolResults = append(toolResults, contentBlock{
303→					Type:      "tool_result",
304→					ToolUseID: tu.ID,
305→					Content:   resultText,
306→				})
307→			}
308→
309→			messages = append(messages, anthropicMessage{
310→				Role:    "user",
311→				Content: toolResults,
312→			})
313→		}
314→
315→		logChatAnswer(chatRowID, strings.TrimSpace(answerText.String()))
316→
317→		writeChunkBuffered(w, chunk{Type: "done"}, &buffer, isCloudFront)
318→		if isCloudFront {
319→			flushBuffer(w, buffer)
320→		}
321→	}
322→}
