101→		if err != nil {
102→			writeJSON(w, map[string]string{"error": "Failed to generate password"}, http.StatusInternalServerError)
103→			return
104→		}
105→		password = generatedPassword
106→		req.RequiresPasswordSetup = true
107→	} else {
108→		if err := ValidatePassword(password); err != nil {
109→			writeJSON(w, map[string]string{"error": err.Error()}, http.StatusBadRequest)
