188→		writeJSON(w, map[string]string{"error": "User ID required"}, http.StatusBadRequest)
189→		return
190→	}
191→	userIDStr := pathParts[3]
192→	targetUserID, err := strconv.ParseInt(userIDStr, 10, 64)
193→	if err != nil {
194→		writeJSON(w, map[string]string{"error": "Invalid user ID"}, http.StatusBadRequest)
195→		return
196→	}
197→
198→	// Parse request
199→	var req struct {
200→		Email         *string `json:"email"`
201→		Username      *string `json:"username"`
202→		IsActive      *bool   `json:"is_active"`
203→		IsAdmin       *bool   `json:"is_admin"`
204→		EmailVerified *bool   `json:"email_verified"`
205→	}
206→
207→	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
208→		writeJSON(w, map[string]string{"error": "Invalid request body"}, http.StatusBadRequest)
209→		return
210→	}
211→
212→	// Get existing user
213→	targetUser, err := GetUserByID(r.Context(), m.DB, m.DBDriver, targetUserID)
214→	if err != nil {
215→		if err == sql.ErrNoRows {
216→			writeJSON(w, map[string]string{"error": "User not found"}, http.StatusNotFound)
217→		} else {
218→			writeJSON(w, map[string]string{"error": "Failed to fetch user"}, http.StatusInternalServerError)
219→		}
220→		return
221→	}
222→
223→	// Update fields if provided
224→	if req.Email != nil {
225→		if err := ValidateEmail(*req.Email); err != nil {
226→			writeJSON(w, map[string]string{"error": err.Error()}, http.StatusBadRequest)
227→			return
228→		}
229→		targetUser.Email = *req.Email
230→	}
231→
232→	if req.Username != nil {
233→		if *req.Username != "" {
234→			if err := ValidateUsername(*req.Username); err != nil {
235→				writeJSON(w, map[string]string{"error": err.Error()}, http.StatusBadRequest)
236→				return
237→			}
238→		}
239→		targetUser.Username = *req.Username
240→	}
241→
242→	if req.IsActive != nil {
243→		targetUser.IsActive = *req.IsActive
244→	}
245→
246→	if req.IsAdmin != nil {
247→		targetUser.IsAdmin = *req.IsAdmin
248→	}
249→
250→	if req.EmailVerified != nil {
251→		targetUser.EmailVerified = *req.EmailVerified
252→	}
253→
254→	// Update user in database
255→	if err := UpdateUser(r.Context(), m.DB, m.DBDriver, targetUser); err != nil {
256→		if strings.Contains(err.Error(), "UNIQUE constraint failed") || strings.Contains(err.Error(), "duplicate key") {
257→			writeJSON(w, map[string]string{"error": "Email or username already in use"}, http.StatusConflict)
258→		} else {
259→			writeJSON(w, map[string]string{"error": "Failed to update user"}, http.StatusInternalServerError)
260→		}
261→		return
262→	}
263→
264→	writeJSON(w, map[string]interface{}{
265→		"message": "User updated successfully",
266→		"user":    targetUser,
267→	}, http.StatusOK)
268→}
