// Chat question logging to DuckLake analytics
// Captures user questions from the web-chat and map widget with request metadata

package main

import (
	"log"
	"net"
	"net/http"
	"strconv"
	"strings"
	"time"
)

// logChatQuestion logs a user's chat question to DuckLake and returns a unique row ID.
// The returned ID can be passed to logChatAnswer to attach the AI response.
func logChatQuestion(r *http.Request, question, source, model, sessionID string, historyLen int, clientTimestamp string) int64 {
	if !duckDBAvailable() {
		return 0
	}

	if len(question) > 5000 {
		question = question[:5000]
	}

	ip := getClientIP(r)
	ua := r.Header.Get("User-Agent")
	isMobile, osName, browser := parseUserAgent(ua)
	country := r.Header.Get("CloudFront-Viewer-Country")
	acceptLang := r.Header.Get("Accept-Language")
	if len(acceptLang) > 200 {
		acceptLang = acceptLang[:200]
	}
	referer := r.Header.Get("Referer")
	isCloudFront := r.Header.Get("CloudFront-Viewer-Country") != "" ||
		r.Header.Get("CloudFront-Forwarded-Proto") != "" ||
		r.Header.Get("X-Amz-Cf-Id") != ""

	// Parse client timestamp; use nil if not provided or invalid
	var clientTS interface{}
	if clientTimestamp != "" {
		clientTS = clientTimestamp
	}

	// Generate unique ID (DuckLake doesn't support RETURNING or sequences)
	id := time.Now().UnixNano()

	_, err := duckDB.Exec(`
		INSERT INTO chat_questions (
			id, question, source, ip_address, user_agent, is_mobile,
			os, browser, country, accept_language, referer,
			session_id, history_length, model, cloudfront, client_timestamp
		) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		id, question, source, ip, ua, isMobile,
		osName, browser, country, acceptLang, referer,
		sessionID, historyLen, model, isCloudFront, clientTS,
	)
	if err != nil {
		log.Printf("chat_questions insert error: %v", err)
		return 0
	}
	return id
}

// logChatAnswer stores the AI's response by deleting and re-inserting the row.
// DuckLake UPDATE has a bug that truncates large string values, so we use DELETE+INSERT instead.
func logChatAnswer(rowID int64, answer string) {
	if !duckDBAvailable() || rowID == 0 {
		return
	}
	if len(answer) > 50000 {
		answer = answer[:50000]
	}
	log.Printf("chat_questions: logChatAnswer called id=%d answer_len=%d first_100=%q", rowID, len(answer), answer[:min(100, len(answer))])
	go func() {
		// DuckLake has bugs with parameterized queries for long strings.
		// Use a simple UPDATE with string literal as workaround.
		escaped := strings.ReplaceAll(answer, "'", "''")
		escaped = strings.ReplaceAll(escaped, "\\", "\\\\")
		query := `UPDATE chat_questions SET answer = '` + escaped + `' WHERE id = ` + strconv.FormatInt(rowID, 10)
		_, err := duckDB.Exec(query)
		if err != nil {
			log.Printf("chat_questions answer update error: %v", err)
		} else {
			log.Printf("chat_questions: answer UPDATE executed for id=%d", rowID)
		}
	}()
}

// getClientIP extracts the client IP from the request, respecting proxy headers.
func getClientIP(r *http.Request) string {
	// X-Forwarded-For may contain multiple IPs: client, proxy1, proxy2
	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
		parts := strings.SplitN(xff, ",", 2)
		ip := strings.TrimSpace(parts[0])
		if ip != "" {
			return ip
		}
	}
	if xri := r.Header.Get("X-Real-IP"); xri != "" {
		return strings.TrimSpace(xri)
	}
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

// parseUserAgent extracts mobile/desktop, OS, and browser from User-Agent string.
func parseUserAgent(ua string) (isMobile bool, osName, browser string) {
	lower := strings.ToLower(ua)

	// Mobile detection
	isMobile = strings.Contains(lower, "mobile") ||
		strings.Contains(lower, "android") && !strings.Contains(lower, "tablet") ||
		strings.Contains(lower, "iphone") ||
		strings.Contains(lower, "ipod")

	// OS detection
	switch {
	case strings.Contains(lower, "iphone") || strings.Contains(lower, "ipad") || strings.Contains(lower, "ipod"):
		osName = "iOS"
	case strings.Contains(lower, "android"):
		osName = "Android"
	case strings.Contains(lower, "windows"):
		osName = "Windows"
	case strings.Contains(lower, "macintosh") || strings.Contains(lower, "mac os"):
		osName = "macOS"
	case strings.Contains(lower, "linux"):
		osName = "Linux"
	case strings.Contains(lower, "cros"):
		osName = "ChromeOS"
	default:
		osName = "Unknown"
	}

	// Browser detection (order matters — check specific before generic)
	switch {
	case strings.Contains(lower, "edg/") || strings.Contains(lower, "edge/"):
		browser = "Edge"
	case strings.Contains(lower, "opr/") || strings.Contains(lower, "opera"):
		browser = "Opera"
	case strings.Contains(lower, "firefox/"):
		browser = "Firefox"
	case strings.Contains(lower, "chrome/") && !strings.Contains(lower, "chromium"):
		browser = "Chrome"
	case strings.Contains(lower, "safari/") && !strings.Contains(lower, "chrome"):
		browser = "Safari"
	case strings.Contains(lower, "chromium"):
		browser = "Chromium"
	default:
		browser = "Unknown"
	}

	return
}

// Chat question logging to DuckLake analytics
// Captures user questions from the web-chat and map widget with request metadata

package main

import (
	"log"
	"net"
	"net/http"
	"strconv"
	"strings"
	"time"
)

// logChatQuestion logs a user's chat question to DuckLake and returns a unique row ID.
// The returned ID can be passed to logChatAnswer to attach the AI response.
func logChatQuestion(r *http.Request, question, source, model, sessionID string, historyLen int, clientTimestamp string) int64 {
	if !duckDBAvailable() {
		return 0
	}

	if len(question) > 5000 {
		question = question[:5000]
	}

	ip := getClientIP(r)
	ua := r.Header.Get("User-Agent")
	isMobile, osName, browser := parseUserAgent(ua)
	country := r.Header.Get("CloudFront-Viewer-Country")
	acceptLang := r.Header.Get("Accept-Language")
	if len(acceptLang) > 200 {
		acceptLang = acceptLang[:200]
	}
	referer := r.Header.Get("Referer")
	isCloudFront := r.Header.Get("CloudFront-Viewer-Country") != "" ||
		r.Header.Get("CloudFront-Forwarded-Proto") != "" ||
		r.Header.Get("X-Amz-Cf-Id") != ""

	// Parse client timestamp; use nil if not provided or invalid
	var clientTS interface{}
	if clientTimestamp != "" {
		clientTS = clientTimestamp
	}

	// Generate unique ID (DuckLake doesn't support RETURNING or sequences)
	id := time.Now().UnixNano()

	_, err := duckDB.Exec(`
		INSERT INTO chat_questions (
			id, question, source, ip_address, user_agent, is_mobile,
			os, browser, country, accept_language, referer,
			session_id, history_length, model, cloudfront, client_timestamp
		) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		id, question, source, ip, ua, isMobile,
		osName, browser, country, acceptLang, referer,
		sessionID, historyLen, model, isCloudFront, clientTS,
	)
	if err != nil {
		log.Printf("chat_questions insert error: %v", err)
		return 0
	}
	return id
}

// logChatQuestionWithAnswer inserts a complete chat_questions row including the answer.
// DuckLake UPDATE silently corrupts large string values, so we do a single INSERT with all fields.
func logChatQuestionWithAnswer(r *http.Request, question, source, model, sessionID string, historyLen int, clientTimestamp string, answer string) {
	if !duckDBAvailable() {
		return
	}

	if len(question) > 5000 {
		question = question[:5000]
	}
	if len(answer) > 50000 {
		answer = answer[:50000]
	}

	ip := getClientIP(r)
	ua := r.Header.Get("User-Agent")
	isMobile, osName, browser := parseUserAgent(ua)
	country := r.Header.Get("CloudFront-Viewer-Country")
	acceptLang := r.Header.Get("Accept-Language")
	if len(acceptLang) > 200 {
		acceptLang = acceptLang[:200]
	}
	referer := r.Header.Get("Referer")
	isCloudFront := r.Header.Get("CloudFront-Viewer-Country") != "" ||
		r.Header.Get("CloudFront-Forwarded-Proto") != "" ||
		r.Header.Get("X-Amz-Cf-Id") != ""

	var clientTS interface{}
	if clientTimestamp != "" {
		clientTS = clientTimestamp
	}

	id := time.Now().UnixNano()

	_, err := duckDB.Exec(`
		INSERT INTO chat_questions (
			id, question, answer, source, ip_address, user_agent, is_mobile,
			os, browser, country, accept_language, referer,
			session_id, history_length, model, cloudfront, client_timestamp
		) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		id, question, answer, source, ip, ua, isMobile,
		osName, browser, country, acceptLang, referer,
		sessionID, historyLen, model, isCloudFront, clientTS,
	)
	if err != nil {
		log.Printf("chat_questions insert (with answer) error: %v", err)
	}
}

// getClientIP extracts the client IP from the request, respecting proxy headers.
func getClientIP(r *http.Request) string {
	// X-Forwarded-For may contain multiple IPs: client, proxy1, proxy2
	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
		parts := strings.SplitN(xff, ",", 2)
		ip := strings.TrimSpace(parts[0])
		if ip != "" {
			return ip
		}
	}
	if xri := r.Header.Get("X-Real-IP"); xri != "" {
		return strings.TrimSpace(xri)
	}
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

// parseUserAgent extracts mobile/desktop, OS, and browser from User-Agent string.
func parseUserAgent(ua string) (isMobile bool, osName, browser string) {
	lower := strings.ToLower(ua)

	// Mobile detection
	isMobile = strings.Contains(lower, "mobile") ||
		strings.Contains(lower, "android") && !strings.Contains(lower, "tablet") ||
		strings.Contains(lower, "iphone") ||
		strings.Contains(lower, "ipod")

	// OS detection
	switch {
	case strings.Contains(lower, "iphone") || strings.Contains(lower, "ipad") || strings.Contains(lower, "ipod"):
		osName = "iOS"
	case strings.Contains(lower, "android"):
		osName = "Android"
	case strings.Contains(lower, "windows"):
		osName = "Windows"
	case strings.Contains(lower, "macintosh") || strings.Contains(lower, "mac os"):
		osName = "macOS"
	case strings.Contains(lower, "linux"):
		osName = "Linux"
	case strings.Contains(lower, "cros"):
		osName = "ChromeOS"
	default:
		osName = "Unknown"
	}

	// Browser detection (order matters — check specific before generic)
	switch {
	case strings.Contains(lower, "edg/") || strings.Contains(lower, "edge/"):
		browser = "Edge"
	case strings.Contains(lower, "opr/") || strings.Contains(lower, "opera"):
		browser = "Opera"
	case strings.Contains(lower, "firefox/"):
		browser = "Firefox"
	case strings.Contains(lower, "chrome/") && !strings.Contains(lower, "chromium"):
		browser = "Chrome"
	case strings.Contains(lower, "safari/") && !strings.Contains(lower, "chrome"):
		browser = "Safari"
	case strings.Contains(lower, "chromium"):
		browser = "Chromium"
	default:
		browser = "Unknown"
	}

	return
}

